  opacity: 1;
  transform: translateY(0);
}

/* Recipe stat badges for quick-scan information */
.recipe-stat-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 1.5rem;
  background: oklch(0.98 0 0);
  border: 1px solid oklch(0.92 0 0);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-foreground);
  transition: all 0.2s ease;
}

.recipe-stat-badge .stat-icon {
  font-size: 1rem;
  line-height: 1;
}

.recipe-stat-badge:hover {
  background: oklch(0.96 0 0);
  transform: translateY(-1px);
  box-shadow: 0 2px 8px oklch(0 0 0 / 0.1);
}

.stat-badge-success {
  background: oklch(0.95 0.05 145);
  border-color: oklch(0.6 0.15 145);
  color: oklch(0.3 0.1 145);
}

.stat-badge-info {
  background: oklch(0.95 0.05 240);
  border-color: oklch(0.6 0.15 240);
  color: oklch(0.3 0.1 240);
}

/* Ingredient section headers */
.ingredient-section-header {
  font-size: 1.125rem;
  font-weight: 600;
  font-family: var(--font-serif);
  color: var(--color-foreground);
  padding: 0.75rem 1rem;
  background: oklch(0.98 0 0);
  border-left: 3px solid var(--color-primary);
  border-radius: 0.375rem;
  margin-top: 0.5rem;
}

/* Empty instructions message styling */
.empty-instructions-message {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 3rem 2rem;
  border-radius: 1rem;
  background: linear-gradient(135deg, oklch(0.98 0 0) 0%, oklch(0.96 0 0) 100%);
  border: 2px dashed oklch(0.88 0 0);
}

.empty-message-icon {
  font-size: 3rem;
  line-height: 1;
  margin-bottom: 1rem;
  opacity: 0.8;
}

.empty-message-title {
  font-size: 1.5rem;
  font-weight: 600;
  font-family: var(--font-serif);
  color: var(--color-foreground);
  margin-bottom: 0.75rem;
}

.empty-message-text {
  font-size: 1rem;
  color: var(--color-muted-foreground);
  line-height: 1.6;
  max-width: 28rem;
}

